import { describe, it, expect, vi, beforeEach } from "vitest";

// getShowcaseTotals feeds the showcase hero. The applicant list only holds
// consented people, so the hero used to read "275 Applicants" for a chapter
// with 404. The totals must count EVERY application and EVERY check-in of the
// chapter (no consent filter), as exact head counts with no rows transferred.

const mocks = vi.hoisted(() => ({ createAdminClient: vi.fn() }));
vi.mock("@/lib/supabase/admin", () => ({ createAdminClient: mocks.createAdminClient }));

import { getShowcaseTotals } from "@/lib/queries/showcase";

function makeCountDb(counts: { total: number; checkedIn: number }) {
  const queries: Array<{ eq: string[]; or: string[]; not: string[]; head: boolean }> = [];
  return {
    queries,
    client: {
      from() {
        const q = { eq: [] as string[], or: [] as string[], not: [] as string[], head: false };
        queries.push(q);
        const builder = {
          select: (_cols: string, opts?: { head?: boolean }) => {
            q.head = Boolean(opts?.head);
            return builder;
          },
          eq: (col: string, val: string) => {
            q.eq.push(`${col}=${val}`);
            return builder;
          },
          or: (f: string) => {
            q.or.push(f);
            return builder;
          },
          not: (col: string) => {
            q.not.push(col);
            return builder;
          },
          then(resolve: (v: { count: number; error: null }) => void) {
            resolve({
              count: q.not.includes("checked_in_at") ? counts.checkedIn : counts.total,
              error: null,
            });
          },
        };
        return builder;
      },
    },
  };
}

beforeEach(() => vi.clearAllMocks());

describe("getShowcaseTotals", () => {
  it("counts every application and every check-in of the chapter", async () => {
    const { client, queries } = makeCountDb({ total: 404, checkedIn: 180 });
    mocks.createAdminClient.mockReturnValue(client);

    const totals = await getShowcaseTotals("chapter-a");

    expect(totals).toEqual({ applicants: 404, participated: 180 });
    expect(queries).toHaveLength(2);
    for (const q of queries) {
      expect(q.head).toBe(true);
      expect(q.eq).toEqual(["chapter_id=chapter-a"]);
      // No consent filter: these are the chapter's real totals.
      expect(q.or).toEqual([]);
    }
  });

  it("throws when a count fails instead of showing 0", async () => {
    const failing = {
      from() {
        const builder = {
          select: () => builder,
          eq: () => builder,
          not: () => builder,
          then(resolve: (v: { count: null; error: Error }) => void) {
            resolve({ count: null, error: new Error("boom") });
          },
        };
        return builder;
      },
    };
    mocks.createAdminClient.mockReturnValue(failing);

    await expect(getShowcaseTotals("chapter-a")).rejects.toThrow("boom");
  });
});

